type StoryTestPlan = { test_plan_id:string; test_plan_hash:string; status:string; story_execution_id:string; story_id:string; story_version?:string; source_change_plan_id:string; source_change_plan_hash:string; changed_paths:string[]; test_impact_report_hash:string; matched_contracts:Array<Record<string,unknown>>; matched_rules:Array<Record<string,unknown>>; required_tests:string[]; recommended_tests:string[]; effective_required_tests:string[]; test_reasons:Record<string,string[]>; test_policy:Record<string,{criticality:string;waivable:boolean;reason:string}>; unknown_impact:{paths:string[];manual_review_required:boolean;fail_closed:boolean}; sensitive_impact:{paths:string[];present:boolean;under_testing_blocked?:boolean}; full_regression_signal:{required_before_backlog_or_release_closure:boolean;informational_only:boolean;execution_authorized:boolean;profile_id?:string}; review?:Record<string,unknown>; active_waivers?:Array<Record<string,unknown>>; expired_waivers?:Array<Record<string,unknown>> };

