  save.disabled=!canAuthor; createPlan.disabled=true; planRecheck.disabled=true; dryRun.disabled=true; requestApproval.disabled=true; apply.disabled=true; requestRollback.disabled=true; rollback.disabled=true; validateStory.disabled=true; approveTestPlan.disabled=true; rejectTestPlan.disabled=true; waiveTestPlan.disabled=true; planValidationJobs.disabled=true; refreshValidationJobs.disabled=true;
  if(!canAuthor)save.title='Solo owner/developer puede persistir SourceDraftBuffer.'; if(!isOwner){requestApproval.title='Solo owner puede solicitar/aplicar.';apply.title=requestApproval.title;requestRollback.title=requestApproval.title;rollback.title=requestApproval.title;approveTestPlan.title='Solo owner puede aprobar StoryTestPlan.';waiveTestPlan.title='Solo owner puede crear waivers.';}

